"""Read actual source specs/archives and new parent provenance,not a native rerun."""
from common import *
rd=lambda p:json.loads(p.read_text());p=rd(R/'plan.json');r=rd(R/'report.json');rh=sha(R/'report.json');b=rd(R/'code_binding_before_evaluation.json');sources={};rows=[]
for fp,z in p['read_only_references'].items():
 if z['scope']!='native':continue
