for c in r['configs'].values():
 sp=rd(ROOT/c['spec']);assert b['immutable_source_sha256'][c['spec']]==sha(ROOT/c['spec']);arc=json.loads(gzip.decompress((ROOT/c['archive']).read_bytes()));fps=c['source_fingerprints'];assert c['scope']=='parent' and arc['spec']==sp and [a['weight'] for a in sp['components']]==[1,1] and sources[fps[0]]['actual_entry_target']==c['W'] and sources[fps[1]]['actual_entry_target']==4000 and sources[fps[1]]['funding_count']==4 and sources[fps[1]]['trend_lag_days']==3 and sources[fps[1]]['funding_budget_vol_window_days']==9 and sources[fps[1]]['funding_budget_vol_ratio']==c['K']
 for k,z in arc['scenes'].items():assert z['native_source_archives_sha256']==[sources[f]['archive_sha256'] for f in fps] and z['source_full_NAV_sha256']==[sources[f]['NAV_hashes'][k] for f in fps] and z['summary']['parent_executions']==0
 rows.append({'fingerprint':c['fingerprint'],'BTC_actual_source_target':c['W'],'ETH_actual_funding_count':4,'ETH_actual_trend_lag_days':3,'ETH_actual_funding_budget_vol_window_days':9,'ETH_actual_funding_budget_volatility_ratio':c['K'],'source_fingerprints':fps,'source_archives_sha256':[sources[f]['archive_sha256'] for f in fps],'raw_weights':[1,1]})
